class ListNode:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next
head = ListNode(7, ListNode(8))
print(head.next.val, head.next.next)

def total(n):
    if n == 0:
        return 0
    return n + total(n - 1)
print(total(4))
